// Flatten Queue: Notion query response -> one item per job page (facts as stored by WF01). Empty / error -> a single meta item (never silent).
const cfg = $('Config').first().json;
const resp = ($input.first() && $input.first().json) || {};
const plain = (a) => (a || []).map((x) => x.plain_text || '').join('');
const pv = (p) => { if (!p) return ''; switch (p.type) { case 'title': return plain(p.title); case 'rich_text': return plain(p.rich_text); case 'number': return p.number; case 'select': return p.select ? p.select.name : ''; case 'url': return p.url || ''; case 'checkbox': return !!p.checkbox; case 'date': return p.date ? p.date.start : ''; default: return ''; } };
if (resp.error || resp.object === 'error' || !Array.isArray(resp.results)) {
  return [{ json: { _kind: 'meta', status: 'QUEUE_ERROR', reason: 'Notion queue query failed: ' + String((resp.error && (resp.error.message || resp.error)) || resp.message || 'bad response').slice(0, 250), errors: [{ stage: 'queue', type: 'notion_error', msg: String((resp.error && resp.error.message) || resp.message || 'bad response').slice(0, 250) }] } }];
}
if (resp.results.length === 0) return [{ json: { _kind: 'meta', status: 'EMPTY_QUEUE', reason: 'no EXTRACTED / re-queued jobs', errors: [] } }];
const out = [];
for (const pg of resp.results) {
  const P = pg.properties || {};
  const visa = String(pv(P['Visa Status']) || '');
  const q = (visa.match(/「([^」]+)」/) || [])[1] || '';
  const notes = String(pv(P['Audit Notes']) || '');
  const status = pv(P['Status']);
  out.push({ json: {
    _kind: 'job', page_id: pg.id, page_url: pg.url, created_time: pg.created_time, status,
    requeued: status === 'VERIFICATION_REQUIRED',
    human_employer_verified: status === 'VERIFICATION_REQUIRED' && pv(P['Employer Verified']) === true,
    job_number: String(pv(P['Job Number']) || '').trim(), title: pv(P['Job Title']), company: String(pv(P['Company']) || '').trim(),
    sector: pv(P['Field']), prefecture: pv(P['Prefecture']), city: pv(P['City']), address: pv(P['Address']),
    monthly_min: pv(P['Monthly Salary Min']) === '' ? null : pv(P['Monthly Salary Min']), monthly_max: pv(P['Monthly Salary Max']) === '' ? null : pv(P['Monthly Salary Max']),
    hourly: pv(P['Effective Hourly Wage']) === '' ? null : pv(P['Effective Hourly Wage']),
    annual_holidays: Number(String(pv(P['Annual Holidays']) || '').replace(/[^0-9]/g, '')) || null,
    source_url: pv(P['Source URL']), ssw_quote: q, quality_score: pv(P['Quality Score']) === '' ? null : pv(P['Quality Score']),
    wf01_notes: notes, wf01_corp: (notes.match(/法人番号:\s*([0-9]{13})/) || [])[1] || '', wf01_run: pv(P['Run ID'])
  } });
}
return out;

// Re-check Source: re-fetch the HelloWork detail page and compare with what WF01 stored. Deterministic. Nothing is trusted from WF01 without re-proof.
const cfg = $('Config').first().json;
const norm = (s) => String(s || '').replace(/[\s　]+/g, '');
const nowJ = new Date(Date.now() + 9 * 3600 * 1000);
const todayUTC = Date.UTC(nowJ.getUTCFullYear(), nowJ.getUTCMonth(), nowJ.getUTCDate());
const md2date = (arr, mode) => { if (!arr || arr.length < 2) return null; const m = Number(arr[0]); const d = Number(arr[1]); if (!m || !d) return null; const y = nowJ.getUTCFullYear(); let t = Date.UTC(y, m - 1, d); if (mode === 'posted' && t > todayUTC + 2 * 86400000) t = Date.UTC(y - 1, m - 1, d); if (mode === 'expiry' && t < todayUTC - 200 * 86400000) t = Date.UTC(y + 1, m - 1, d); return t; };
const toText = (h) => String(h || '').replace(/<script[\s\S]*?<\/script>/gi, '').replace(/<style[\s\S]*?<\/style>/gi, '').replace(/<br\s*\/?>/gi, '\n').replace(/<\/(p|div|tr|li|h\d|table|dt|dd)>/gi, '\n').replace(/<[^>]+>/g, '\n').replace(/&nbsp;/g, ' ').replace(/&amp;/g, '&').replace(/&lt;/g, '<').replace(/&gt;/g, '>').replace(/\n[ \t　]*(?=\n)/g, '').replace(/\n{2,}/g, '\n').trim();
const OVERSEAS_OK = [/海外(在住)?(の方|者)?(から|在住).{0,8}(応募|可|歓迎|OK|ＯＫ)/, /(国外|海外)在住.{0,4}(可|OK|ＯＫ|歓迎)/, /来日前.{0,12}(応募|面接|内定|選考)/, /(入国前|渡日前).{0,12}(応募|面接|内定|選考)/, /(海外|来日前).{0,20}オンライン面接|オンライン面接.{0,20}(海外|来日前)/];
const DOMESTIC = [/(海外|国外)在住.{0,4}(不可|不可能|ＮＧ|NG)/, /国内(に)?在住(の方|者)?(のみ|限)/, /日本(国)?内に(在住|居住).{0,10}(方|者|必須)/, /在留カード.{0,12}(必須|をお持ちの方のみ)/];
const hit = (arr, t) => { for (const r of arr) { const m = t.match(r); if (m) return m[0].slice(0, 80); } return ''; };
const out = [];
const inputs = $input.all();
for (let k = 0; k < inputs.length; k++) {
  const it = inputs[k];
  let job = {};
  try { job = $('Flatten Queue').itemMatching(k).json; } catch (e) { job = {}; }
  const err = it.json && it.json.error;
  const html = (it.json && it.json.data) || '';
  const errors = [];
  const rc = { source_state: 'OK', host_ok: /^https:\/\/(www\.)?hellowork\.careers\//.test(job.source_url || '') || /^https:\/\/www\.hellowork\.mhlw\.go\.jp\//.test(job.source_url || ''), conflicts: [] };
  let text = '';
  if (err) { const m = String(err.message || err.description || err); rc.source_state = /404|410|not found/i.test(m) ? 'GONE' : 'UNREACHABLE'; rc.detail = m.slice(0, 200); errors.push({ stage: 'source_fetch', type: rc.source_state, msg: m.slice(0, 200) }); }
  else if (typeof html !== 'string' || html.length < 3000) { rc.source_state = /Fatal error|detail\.php/.test(String(html)) ? 'BROKEN' : 'UNREACHABLE'; rc.detail = 'response too short (' + String(html || '').length + ')'; errors.push({ stage: 'source_fetch', type: rc.source_state, msg: rc.detail }); }
  else {
    const full = toText(html);
    const start = full.indexOf('の募集内容、仕事概要');
    if (/(掲載を終了|受付を終了|募集を終了|求人は終了|この求人は.{0,6}(終了|締め切)|ページが見つかりません)/.test(full.slice(0, 4000)) && start < 0) rc.source_state = 'CLOSED_ON_SOURCE';
    const body = (start >= 0 ? full.slice(Math.max(0, start - 80)) : full).slice(0, 12000);
    text = body;
    const lines = body.split('\n').map((s) => s.trim()).filter((s) => s.length);
    const after = (label) => { const i = lines.indexOf(label); return i >= 0 && i + 1 < lines.length ? lines[i + 1] : ''; };
    const hdr = lines.find((l) => /の募集内容、仕事概要$/.test(l));
    rc.page_company = hdr ? hdr.replace(/の募集内容、仕事概要$/, '').trim() : '';
    const wi = lines.indexOf('勤務地');
    rc.page_address = wi >= 0 ? lines.slice(wi + 1, wi + 4).filter((l) => !/^〒/.test(l) && !/^就業場所|^マイカー|^転勤/.test(l))[0] || '' : '';
    rc.haken = after('派遣・請負等'); rc.wage_text = after('賃金'); rc.wage_form = after('賃金形態'); rc.annual_text = after('年間休日');
    const wnum = String(rc.wage_text).replace(/,/g, '').match(/([0-9]{4,7})/);
    rc.wage_min = wnum ? Number(wnum[1]) : null;
    const hm = String(rc.wage_form).replace(/,/g, '').match(/時給([0-9]{3,5})/);
    rc.hourly = hm ? Number(hm[1]) : null;
    rc.annual = Number(String(rc.annual_text).replace(/[^0-9]/g, '')) || null;
    const posted = md2date((full.match(/受理日：([0-9]{1,2})月([0-9]{1,2})日/) || []).slice(1, 3), 'posted');
    const expiry = md2date((full.match(/有効期限：([0-9]{1,2})月([0-9]{1,2})日/) || []).slice(1, 3), 'expiry');
    rc.days_left = expiry ? Math.round((expiry - todayUTC) / 86400000) : null;
    rc.posted_age_days = posted ? Math.round((todayUTC - posted) / 86400000) : null;
    rc.page_corp = (body.match(/法人番号[^0-9]{0,6}([0-9]{13})/) || [])[1] || '';
    const jn = String(job.job_number || '').replace(/-/g, '');
    rc.source_job_match = !!jn && full.replace(/-/g, '').indexOf(jn) >= 0;
    rc.ssw_in_text = body.indexOf('特定技能') >= 0;
    rc.ssw_quote_ok = !!job.ssw_quote && job.ssw_quote.length >= 4 && norm(body).indexOf(norm(job.ssw_quote)) >= 0;
    rc.overseas_hit = hit(OVERSEAS_OK, body); rc.domestic_hit = hit(DOMESTIC, body);
    // conflicts vs WF01-stored facts
    if (job.monthly_min && rc.wage_min && !job.hourly && Math.abs(job.monthly_min - rc.wage_min) > Math.max(1000, job.monthly_min * 0.01)) rc.conflicts.push('salary: stored ' + job.monthly_min + ' vs source ' + rc.wage_min);
    if (job.hourly && rc.hourly && job.hourly !== rc.hourly) rc.conflicts.push('hourly: stored ' + job.hourly + ' vs source ' + rc.hourly);
    if (job.annual_holidays && rc.annual && job.annual_holidays !== rc.annual) rc.conflicts.push('annual holidays: stored ' + job.annual_holidays + ' vs source ' + rc.annual);
    if (job.wf01_corp && rc.page_corp && job.wf01_corp !== rc.page_corp) rc.conflicts.push('法人番号: stored ' + job.wf01_corp + ' vs source ' + rc.page_corp);
    const core = (s) => String(s || '').normalize('NFKC').replace(/株式会社|有限会社|合同会社|\(株\)|\(有\)|[\s　]/g, '');
    if (job.company && rc.page_company && core(job.company) !== core(rc.page_company)) rc.conflicts.push('company: stored ' + job.company + ' vs source ' + rc.page_company);
  }
  const base = Object.assign({}, job, { rc, detail_text: text, errors });
  base.dup_query_body = job.company
    ? { filter: { property: 'Company', rich_text: { equals: job.company } }, page_size: 25 }
    : { filter: { property: 'Job Number', rich_text: { equals: job.job_number } }, page_size: 25 };
  out.push({ json: base });
}
return out;

// Duplicate / Conflict check against Master Job DB (same company). Notion is the source of truth.
const norm = (s) => String(s || '').normalize('NFKC').replace(/[\s　]+/g, '');
const plain = (a) => (a || []).map((x) => x.plain_text || '').join('');
const out = [];
const inputs = $input.all();
for (let k = 0; k < inputs.length; k++) {
  const it = inputs[k];
  let job = {};
  try { job = $('Re-check Source').itemMatching(k).json; } catch (e) { job = {}; }
  const errors = (job.errors || []).slice();
  const res = it.json && Array.isArray(it.json.results) ? it.json.results : null;
  let dup = { state: 'Unknown', note: '' };
  if (!res || (it.json && it.json.error)) { dup.note = 'duplicate query failed'; errors.push({ stage: 'dup_check', type: 'notion_error', msg: String((it.json && it.json.error && it.json.error.message) || 'bad response').slice(0, 200) }); }
  else {
    dup = { state: 'Unique', note: '' };
    const advanced = ['VERIFIED', 'CONTENT_READY', 'IMAGE_READY', 'APPROVED', 'PUBLISHED', 'UPDATED'];
    for (const o of res) {
      if (o.id === job.page_id) continue;
      const P = o.properties || {};
      const ojn = plain((P['Job Number'] || {}).rich_text).trim();
      const ot = plain((P['Job Title'] || {}).title);
      const oc = plain((P['City'] || {}).rich_text); const os = P['Status'] && P['Status'].select ? P['Status'].select.name : '';
      const earlier = String(o.created_time) <= String(job.created_time) || advanced.indexOf(os) >= 0;
      if (ojn && ojn === job.job_number && earlier) { dup = { state: 'Duplicate', note: 'same Job Number as ' + o.id + ' (' + os + ')' }; break; }
      if (norm(ot) === norm(job.title) && norm(oc) === norm(job.city) && earlier && dup.state !== 'Duplicate') dup = { state: 'Possible Duplicate', note: 'same company+title+city as ' + o.id + ' (' + os + ', job ' + ojn + ')' };
    }
  }
  out.push({ json: Object.assign({}, job, { dup, errors, dup_query_body: undefined }) });
}
return out;

// Build Registry Request: company verification is its own process (not dependent on 法人番号 being printed in the posting).
const cfg = $('Config').first().json;
const corpOK = (c) => { if (!/^[0-9]{13}$/.test(c || '')) return false; const d = c.split('').map(Number); let s = 0; for (let n = 1; n <= 12; n++) { const p = d[13 - n]; s += p * (n % 2 === 1 ? 1 : 2); } return (9 - (s % 9)) === d[0]; };
const base = String(cfg.gbiz_base || 'https://info.gbiz.go.jp/hojin').replace(/\/$/, '');
const out = [];
for (const it of $input.all()) {
  const j = it.json; const rc = j.rc || {};
  const given = [rc.page_corp, j.wf01_corp].filter((c) => corpOK(c))[0] || '';
  const name = String(rc.page_company || j.company || '').normalize('NFKC').replace(/[\s　]+/g, '');
  let mode = 'NONE'; let url = base + '/v1/hojin?name=' + encodeURIComponent('__none__') + '&limit=1';
  if (given) { mode = 'BY_NUMBER'; url = base + '/v1/hojin/' + given; }
  else if (name) { mode = 'BY_NAME'; url = base + '/v1/hojin?name=' + encodeURIComponent(name) + '&limit=20'; }
  out.push({ json: Object.assign({}, j, { gbiz: { mode, url, given_number: given } }) });
}
return out;

// Company Score: match registry record vs posting on 法人番号 + name + address (+ active status). Deterministic, facts only.
const cfg = $('Config').first().json;
const th = Number(cfg.company_threshold) || 90;
const N = (s) => String(s || '').normalize('NFKC').replace(/[\s　]+/g, '');
const core = (s) => N(s).replace(/株式会社|有限会社|合同会社|合資会社|合名会社|一般社団法人|一般財団法人|公益社団法人|公益財団法人|社会福祉法人|医療法人社団|医療法人財団|医療法人|農事組合法人|協同組合|\(株\)|\(有\)|\(同\)|\(社\)|\(医\)|\(福\)/g, '').replace(/[()（）]/g, '');
const corpOK = (c) => { if (!/^[0-9]{13}$/.test(c || '')) return false; const d = c.split('').map(Number); let s = 0; for (let n = 1; n <= 12; n++) { const p = d[13 - n]; s += p * (n % 2 === 1 ? 1 : 2); } return (9 - (s % 9)) === d[0]; };
const nameMatch = (a, b) => { const x = core(a); const y = core(b); if (!x || !y) return 'NONE'; if (x === y) return 'EXACT'; const [s, l] = x.length <= y.length ? [x, y] : [y, x]; return (l.indexOf(s) >= 0 && s.length / l.length >= 0.7) ? 'PARTIAL' : 'NONE'; };
const addrMatch = (loc, j) => { const L = N(loc); const pref = N(j.prefecture); const city = N(j.city); const rcA = N((j.rc && j.rc.page_address) || ''); const A = N(j.address); let lvl = 'NONE';
  if (pref && L.indexOf(pref) >= 0) lvl = 'PREF';
  if (!pref && rcA) { const m = rcA.match(/^(.{2,3}?[都道府県])/); if (m && L.indexOf(m[1]) >= 0) lvl = 'PREF'; }
  const cityTxt = city || (rcA.replace(/^.{2,3}?[都道府県]/, '').match(/^(.{1,6}?[市区町村郡])/) || [])[1] || '';
  if (cityTxt && L.indexOf(cityTxt) >= 0 && (lvl === 'PREF' || !pref)) lvl = 'CITY';
  return lvl; };
const out = [];
const inputs = $input.all();
for (let k = 0; k < inputs.length; k++) {
  const it = inputs[k];
  let j = {};
  try { j = $('Build Registry Request').itemMatching(k).json; } catch (e) { j = {}; }
  const errors = (j.errors || []).slice();
  const g = j.gbiz || {}; const rc = j.rc || {};
  const co = { verdict: 'REVIEW', score: 0, parts: { number: 0, name: 0, address: 0, active: 0, direct: 0 }, number: '', number_source: 'NONE', number_confirmed: false, registry_name: '', registry_location: '', active: null, notes: [], conflict: '' };
  const err = it.json && it.json.error;
  const arr = it.json && (it.json['hojin-infos'] || it.json.hojin_infos || it.json.hojinInfos);
  const msg = err ? String(err.message || err.description || err) : '';
  if (g.mode === 'NONE') { co.verdict = 'REVIEW'; co.notes.push('no company name or 法人番号 to search'); }
  else if (err) {
    if (/404|not found/i.test(msg)) { co.notes.push('registry: not found (' + g.mode + ')'); if (g.mode === 'BY_NUMBER') co.conflict = '法人番号 ' + g.given_number + ' not found in registry'; }
    else { co.verdict = 'REGISTRY_UNAVAILABLE'; co.notes.push('registry request failed: ' + msg.slice(0, 120)); errors.push({ stage: 'registry', type: /401|403|unauthor|forbidden/i.test(msg) ? 'auth' : 'request', msg: msg.slice(0, 200) }); }
  } else if (!Array.isArray(arr)) { co.verdict = 'REGISTRY_UNAVAILABLE'; co.notes.push('registry: unexpected response shape'); errors.push({ stage: 'registry', type: 'shape', msg: 'no hojin-infos array' }); }
  else {
    const postName = rc.page_company || j.company;
    let pick = null;
    if (g.mode === 'BY_NUMBER') { pick = arr.filter((x) => x.corporate_number === g.given_number)[0] || null; if (!pick) co.notes.push('registry returned no matching record for ' + g.given_number); }
    else {
      const cands = arr.filter((x) => nameMatch(x.name, postName) === 'EXACT' && addrMatch(x.location, j) === 'CITY');
      if (cands.length === 1) pick = cands[0];
      else if (cands.length > 1) co.notes.push('ambiguous: ' + cands.length + ' registry records match name+city');
      else { const loose = arr.filter((x) => nameMatch(x.name, postName) !== 'NONE'); co.notes.push('no registry record matches name+city (' + arr.length + ' returned, ' + loose.length + ' loose name hits)'); }
    }
    if (pick) {
      co.registry_name = pick.name || ''; co.registry_location = pick.location || ''; co.number = pick.corporate_number || '';
      co.number_source = g.mode === 'BY_NUMBER' ? 'POSTING' : 'REGISTRY_DISCOVERED';
      const nm = nameMatch(pick.name, postName); const am = addrMatch(pick.location, j);
      co.parts.number = corpOK(co.number) ? 35 : 0; co.number_confirmed = co.parts.number === 35;
      co.parts.name = nm === 'EXACT' ? 25 : nm === 'PARTIAL' ? 12 : 0;
      co.parts.address = am === 'CITY' ? 20 : am === 'PREF' ? 8 : 0;
      const closed = !!pick.close_date || /閉鎖|解散|清算|合併|廃止/.test(String(pick.status || '') + String(pick.close_cause || ''));
      co.active = !closed; co.parts.active = closed ? 0 : 10;
      if (nm === 'NONE') co.conflict = '法人番号 ' + co.number + ' belongs to 「' + co.registry_name + '」 but posting says 「' + postName + '」';
      if (closed) { co.verdict = 'CLOSED'; co.notes.push('registry marks company closed: ' + String(pick.status || '') + ' ' + String(pick.close_date || '')); }
    }
  }
  const dispatch = (/派遣|請負/.test(rc.haken || '') && !/(ではない|でない|ではありません|なし)/.test(rc.haken || ''));
  co.parts.direct = (!dispatch && rc.source_state === 'OK') ? 10 : 0;
  co.score = co.parts.number + co.parts.name + co.parts.address + co.parts.active + co.parts.direct;
  if (co.verdict !== 'CLOSED' && co.verdict !== 'REGISTRY_UNAVAILABLE') co.verdict = (co.score >= th && !co.conflict) ? 'VERIFIED' : 'REVIEW';
  co.registry_status = co.verdict;
  // Per-record manual override ONLY: a human ticked Employer Verified. Affects the registry verdict alone; every other gate still runs. CLOSED is never overridden.
  if (j.human_employer_verified && (co.verdict === 'REVIEW' || co.verdict === 'REGISTRY_UNAVAILABLE')) { co.verdict = 'MANUAL_VERIFIED'; co.notes.push('Employer Verified ticked by a human in Notion (registry status: ' + co.registry_status + '; NOT registry-verified)'); }
  const hard = rc.source_state === 'GONE' || rc.source_state === 'CLOSED_ON_SOURCE' || dispatch || (j.dup && j.dup.state === 'Duplicate') || co.verdict === 'CLOSED' || (rc.days_left !== null && rc.days_left !== undefined && rc.days_left < 0) || (rc.source_state === 'OK' && !rc.ssw_in_text);
  const needs_ai = !hard && !!j.detail_text && rc.source_state === 'OK';
  out.push({ json: Object.assign({}, j, { co: co, errors, needs_ai: needs_ai ? 'true' : 'false' }) });
}
return out;

// Prepare Verify: AI second opinion on judgement-type checks only. AI may propose; deterministic code verifies every quote and can only DOWNGRADE.
const cfg = $('Config').first().json;
const SYSTEM = `あなたは求人票の「検証」専用エンジンです。与えられた求人票テキストに書かれていることだけを根拠に判定します。推測・一般知識・補完は禁止。判断できない場合は必ず UNKNOWN / UNVERIFIED にします。
出力はJSONオブジェクトのみ（前後の説明・コードフェンス禁止）。引用は求人票テキストからの一字一句そのままの抜粋（60字以内）。見つからなければ ""。
判定項目:
1. employer_is_direct: この求人の雇用主が自社で直接雇用する事業者なら true。派遣・紹介・請負・登録支援機関・協同組合・プラットフォーム運営なら false。不明なら "UNKNOWN"。employer_quote に根拠引用。
2. ssw_recruit_explicit: この求人自体が特定技能外国人を採用対象としていると明記されているなら true。単なる在籍/活躍/社員区分の言及、管理・支援側の仕事なら false。ssw_quote に根拠引用。
3. role_is_management: 仕事内容が特定技能外国人の「管理・教育・支援・通訳」側の役割なら true、そうでなければ false。
4. overseas_applicability: 海外在住のまま応募・面接・内定が可能と明記されていれば "VERIFIED"、国内在住者のみ/在留カード必須等と明記なら "DOMESTIC_ONLY"、明記なしは "UNVERIFIED"（ハローワーク求人というだけでは UNVERIFIED）。overseas_quote に根拠引用。
5. salary_basis_ok: 賃金が残業代・歩合に依存せず基本給で成立していれば true、依存していれば false、不明なら "UNKNOWN"。salary_concern に一言。
